let survived = 0
const MATCH = process.env.MUTANTS_MATCH ?? ''
const arg = (name) => process.argv.find((a) => a.startsWith(`--${name}`))?.split('=')[1] ?? (process.argv.includes(`--${name}`) ? '' : undefined)

// --check-only: every mutant's original text is still in its file exactly once. Seconds, no tests run.
if (arg('check-only') !== undefined) {
  let missing = 0
  for (const [file, from, , what] of MUTANTS) {
    if (readFileSync(file, 'utf8').split(from).length !== 2) {
      console.log(`MISSING ${file}: ${what}`)
      missing++
    }
  }
  console.log(`${MUTANTS.length - missing} / ${MUTANTS.length} originals present exactly once`)
  process.exit(missing ? 1 : 0)
}

/**
 * --since=<ref> (rules G2 step 0, v0.18): only the mutants whose result this branch can have changed.
 * A mutant's result changes only if its code or its tests change, so this runs: mutants new since <ref>; mutants whose
 * original lies within CONTEXT lines of a line the branch changed; mutants whose tests, or the harness those tests run on,
 * lost or changed a line (an added line cannot weaken a test). Every other mutant is checked with --check-only.
 * Tests are judged by test group (owner 2026-11-24, rules §3): a changed line inside a test counts for that test, inside a
 * describe but outside its tests for every test of the describe, outside every describe for the whole file. A mutant whose
 * command picks tests by name (-t / -g) runs only if one of the changed tests matches that name.
 */
function sinceSelection(ref) {
  const git = (...a) => execSync(['git', ...a].map((x) => `'${x.replace(/'/g, `'\\''`)}'`).join(' '), { encoding: 'utf8', maxBuffer: 1 << 28 })
  const CONTEXT = 3
  const baseScript = (() => {
    try {
      return git('show', `${ref}:scripts/mutation-check.mjs`)
    } catch {
      return ''
    }
  })()
  // a mutant is new unless the base defines the same file, original, replacement, label and command (a label alone is not unique)
  const fresh = newMutants(MUTANTS, mutantsOf(baseScript))
  const changedLines = new Map()
  const linesOf = (file) => {
    if (!changedLines.has(file)) {
      const ranges = []
      for (const m of git('diff', '-U0', ref, '--', file).matchAll(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/gm)) {
        const start = Number(m[1])
        const count = m[2] === undefined ? 1 : Number(m[2])
        ranges.push([start, start + Math.max(count, 1) - 1])
      }
      changedLines.set(file, ranges)
    }
    return changedLines.get(file)
  }
  const lostLines = (file) => /^-(?!--)/m.test(git('diff', '-U0', ref, '--', file))
  /** The tests of a test file that lost or changed a line: lost lines in its old text, the lines that replaced them in the new. */
  const touched = new Map()
  const touchedIn = (file) => {
    if (!touched.has(file)) {
      let before = ''
      try {
        before = git('show', `${ref}:${file}`)
      } catch {}
      const [oldLines, newLines] = [[], []]
      for (const m of git('diff', '-U0', ref, '--', file).matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)) {
        const [a, b, c, d] = [Number(m[1]), m[2] === undefined ? 1 : Number(m[2]), Number(m[3]), m[4] === undefined ? 1 : Number(m[4])]
        if (!b) continue // only added lines: they cannot weaken a test
        for (let k = 0; k < b; k++) oldLines.push(a + k)
        for (let k = 0; k < d; k++) newLines.push(c + k)
      }
      const was = before ? touchedTests(before, oldLines) : []
      const now = touchedTests(readFileSync(file, 'utf8'), newLines)
      touched.set(file, was === 'all' || now === 'all' ? 'all' : [...was, ...now])
    }
    return touched.get(file)
  }
  const HARNESS = { vitest: ['src/store/testdb.ts', 'vitest.config.ts'], playwright: ['e2e/serve.ts', 'playwright.config.ts'], demo: ['e2e-demo/serve.ts', 'playwright.demo.config.ts'] }
  const harnessChanged = { vitest: HARNESS.vitest.some(lostLines), playwright: HARNESS.playwright.some(lostLines), demo: HARNESS.demo.some(lostLines) }
  const out = []
  for (const m of MUTANTS) {
    const [file, from, , , cmd] = m
    const why = []
    if (fresh.has(m)) why.push('new')
    const text = readFileSync(file, 'utf8')
    const at = text.indexOf(from)
    if (at >= 0) {
      const first = text.slice(0, at).split('\n').length
      const last = first + from.split('\n').length - 1
      if (linesOf(file).some(([a, b]) => a <= last + CONTEXT && b >= first - CONTEXT)) why.push('code changed')
    } else why.push('missing')
    const tests = cmd.match(/(?:src|e2e-demo|e2e|scripts)\/[\w./-]+\.(?:test|spec)\.ts/g) ?? []
    if (tests.some((f) => picks(cmd, touchedIn(f), readFileSync(f, 'utf8')))) why.push('tests changed')
    if (harnessChanged[cmd.includes('playwright.demo.config') ? 'demo' : cmd.includes('playwright') ? 'playwright' : 'vitest']) why.push('harness changed')
    if (why.length) out.push(m)
  }
  return out
}

const since = arg('since')
const pool = since ? sinceSelection(since) : MUTANTS
if (since) console.log(`--since=${since}: ${pool.length} of ${MUTANTS.length} mutants can have changed; run --check-only for the rest`)
if (arg('list') !== undefined) {
  for (const [f, , , what] of pool) console.log(`  ${f}: ${what}`)
  process.exit(0)
}
const selected = pool.filter(([f, , , what]) => `${f} ${what}`.includes(MATCH))
if (!selected.length) {
  console.log('no mutants selected')
  process.exit(0)
}
// Stop at the first failing test: a mutant is caught by one failure, the rest of the suite adds nothing (rules §3).
const fast = (cmd) => cmd.replace(/vitest run /, 'vitest run --bail=1 ').replace(/playwright test /, 'playwright test --max-failures=1 ')
// Every suite these mutants use must pass first (a suite already failing would count each of them as caught), and its time
// sets each mutant's limit: three times the normal time plus a minute. A mutant still running then is caught (a test that
// never ends fails), and listed as such to be looked at (Stryker and PIT do the same, rules §3).
const limit = new Map()
for (const cmd of new Set(selected.map((m) => m[4]))) {
  const t0 = Date.now()
  try {
    execSync(fast(cmd), { stdio: 'ignore' })
  } catch {
    console.log(`the unmutated tests fail: fix them before the mutation check (${cmd})`)
    process.exit(1)
  }
  limit.set(cmd, 3 * (Date.now() - t0) + 60_000)
}
let timedOut = 0
/** Runs a suite in its own process group, so a limit ends the shell and every test process under it. */
const runWithin = (cmd, ms) =>
  new Promise((done) => {
    const child = spawn('sh', ['-c', cmd], { stdio: 'ignore', detached: true })
    const timer = setTimeout(() => {
      try {
        process.kill(-child.pid, 'SIGKILL')
      } catch {}
      done('timeout')
    }, ms)
    child.on('exit', (code) => {
      clearTimeout(timer)
      done(code === 0 ? 'passed' : 'failed')
    })
  })

for (const [file, from, to, what, cmd] of selected) {
  const orig = readFileSync(file, 'utf8')
  if (orig.split(from).length !== 2) {
    console.log(`MISSING ${file}: original text not found exactly once (${what})`)
    survived++
    continue
  }
  writeFileSync(file, orig.replace(from, () => to))
  let result
  try {
    result = await runWithin(fast(cmd), limit.get(cmd))
  } finally {
    writeFileSync(file, orig)
  }
  const caught = result !== 'passed'
  const late = result === 'timeout'
  if (late) timedOut++
  console.log(`${late ? 'TIMEOUT ' : caught ? 'caught  ' : 'SURVIVED'} ${file}: ${what}`)
  if (!caught) survived++
}
console.log(`${selected.length - survived} / ${selected.length} caught${timedOut ? ` (${timedOut} by running past the limit: check each)` : ''}`)
process.exit(survived ? 1 : 0)
